import { plainDate } from '@absoluteui/core';
import { Gantt, type GanttDependency, type GanttTask } from '@absoluteui/components/gantt';

const tasks: GanttTask[] = [
  { id: 'design', parentId: null, label: 'Design', start: plainDate(2026, 9, 28), duration: 5 },
  { id: 'build', parentId: null, label: 'Build', start: plainDate(2026, 9, 28), duration: 10, progress: 20 },
  { id: 'launch', parentId: null, label: 'Launch', start: plainDate(2026, 9, 28), duration: 0 },
];
const dependencies: GanttDependency[] = [
  { id: 'd1', from: 'design', to: 'build' },
  { id: 'd2', from: 'build', to: 'launch', lag: 2 },
];

const host = document.createElement('div');
document.body.append(host);
const gantt = Gantt.create(host, { label: 'Website relaunch', tasks, dependencies, columns: ['name', 'start', 'end', 'duration', 'progress'] });
document.body.dataset.finish = gantt.schedule.finish ? `${String(gantt.schedule.finish.month)}/${String(gantt.schedule.finish.day)}` : '';

import { plainDate } from '@absoluteui/core';
import { Gantt, type GanttTask, type GanttTaskChangeDetail } from '@absoluteui/components/gantt';

let saved: GanttTask[] = [
  { id: 'phase', parentId: null, label: 'Phase 1', start: plainDate(2026, 10, 1), duration: 0 },
  { id: 'a', parentId: 'phase', label: 'Research', start: plainDate(2026, 10, 1), duration: 3 },
  { id: 'b', parentId: 'phase', label: 'Prototype', start: plainDate(2026, 10, 1), duration: 4, manual: true },
];

const host = document.querySelector<HTMLElement>('#plan');
if (host) {
  Gantt.create(host, {
    label: 'Phase plan',
    tasks: saved,
    dependencies: [{ id: 'ab', from: 'a', to: 'b' }],
    editable: true,
    scale: 'day',
    calendar: { workingDays: [1, 2, 3, 4, 5], holidays: [{ date: plainDate(2026, 10, 5), name: 'Company day' }] },
    // Prototype dates are owned by another team.
    canEdit: (task) => task.id !== 'b',
  });
  host.addEventListener('aui-task-change', (event) => {
    const detail = (event as CustomEvent<GanttTaskChangeDetail>).detail;
    if (detail.schedule.finish && detail.schedule.finish.month > 11) event.preventDefault();
    else saved = detail.tasks;
  });
}

import { plainDate } from '@absoluteui/core';
import { Gantt } from '@absoluteui/components/gantt';

const host = document.createElement('div');
document.body.append(host);
const gantt = Gantt.create(host, {
  label: 'Migration',
  tasks: [
    { id: 'plan', parentId: null, label: 'Plan', start: plainDate(2026, 10, 5), duration: 3, assignments: [{ resourceId: 'ana' }], baseline: { start: plainDate(2026, 10, 5), end: plainDate(2026, 10, 6) } },
    { id: 'move', parentId: null, label: 'Move data', start: plainDate(2026, 10, 6), duration: 4, assignments: [{ resourceId: 'ana', units: 50 }, { resourceId: 'ben' }] },
  ],
  resources: [{ id: 'ana', label: 'Ana' }, { id: 'ben', label: 'Ben', capacity: 80 }],
  columns: ['name', 'start', 'end', 'resources', 'float'],
  showHistogram: true,
});
const overloaded = gantt.resourceLoad().filter((r) => r.overDays > 0).map((r) => r.resourceId);
host.dataset.overloaded = overloaded.join(',');

import { plainDate } from '@absoluteui/core';
import { createBusinessCalendar } from '@absoluteui/components/business-calendar';
import { assertGantt, scheduleGantt, type GanttDependency, type GanttTask } from '@absoluteui/components/gantt';

const tasks: GanttTask[] = [
  { id: 'a', parentId: null, label: 'Pour foundation', start: plainDate(2026, 10, 1), duration: 2 },
  { id: 'b', parentId: null, label: 'Cure', start: plainDate(2026, 10, 1), duration: 5 },
];
const dependencies: GanttDependency[] = [{ id: 'ab', from: 'a', to: 'b', type: 'FS', lag: 1 }];
assertGantt(tasks, dependencies, undefined);
const schedule = scheduleGantt(tasks, dependencies, createBusinessCalendar({ workingDays: [1, 2, 3, 4, 5, 6] }));
const cure = schedule.tasks.get('b');
document.body.dataset.cure = cure ? `${String(cure.start.day)}-${String(cure.end.day)}, critical ${String(cure.critical)}` : '';
